package com.tripmateai.mapper; import com.tripmateai.dto.response.favorite.FavoriteResponse; import com.tripmateai.entity.Favorite; import com.tripmateai.enums.FavoriteTargetType; public final class FavoriteMapper {private FavoriteMapper(){} public static FavoriteResponse toResponse(Favorite f){if(f.getDestination()!=null)return new FavoriteResponse(f.getId(),FavoriteTargetType.DESTINATION,f.getDestination().getId(),f.getDestination().getCity());if(f.getHotel()!=null)return new FavoriteResponse(f.getId(),FavoriteTargetType.HOTEL,f.getHotel().getId(),f.getHotel().getName());if(f.getRestaurant()!=null)return new FavoriteResponse(f.getId(),FavoriteTargetType.RESTAURANT,f.getRestaurant().getId(),f.getRestaurant().getName());return new FavoriteResponse(f.getId(),FavoriteTargetType.ATTRACTION,f.getAttraction().getId(),f.getAttraction().getName());}}
